INSERT INTO support_settings (id) VALUES (1)
INSERT INTO faq_entries (id, position, published, question_en, answer_en, question_ru, answer_ru) VALUES
  ('access', 10, TRUE, 'How do I get access?', 'An administrator will create your account and give you a one-time code. Enter your email and activation code, then set a four-digit PIN. You can enable biometrics during setup or later in your profile.', 'Как получить доступ?', 'Администратор создаст учётную запись и передаст одноразовый код. Введите email и код активации, затем задайте PIN из четырёх цифр. Биометрию можно включить при настройке или позднее в профиле.'),
  ('pin-or-phone', 20, TRUE, 'What if I forget my PIN or change phones?', 'Ask an administrator for a new activation code. After signing in, set a new PIN. Your old device will lose access, and your accounts and history will appear on the new one.', 'Что делать, если я забыл PIN или сменил телефон?', 'Попросите администратора выдать новый код активации. После входа задайте новый PIN. Доступ с прежнего устройства завершится, а счета и история появятся на новом.'),
  ('record-expense', 30, TRUE, 'How do I add an expense?', 'Open Payments / transfers, choose Record expense, enter the account, amount, category and date, then save the entry.', 'Как добавить расход?', 'Откройте «Платежи/переводы», выберите «Записать расход», укажите счёт, сумму, категорию и дату, затем сохраните запись.'),
  ('currency-transfer', 40, TRUE, 'How do I record a transfer between accounts in different currencies?', 'Choose your debit and credit accounts and enter the actual amount for each one. The entry updates both balances and appears in their histories.', 'Как записать перевод между счетами в разных валютах?', 'Выберите свои счета списания и зачисления и введите обе фактические суммы. Запись обновит остатки двух счетов и появится в их истории.'),
  ('deposit-interest', 50, TRUE, 'How do I record interest on a deposit?', 'When the bank credits interest, record income on the deposit account and choose Deposit interest. The rate on the deposit card is for reference.', 'Как учесть проценты по вкладу?', 'Когда банк начислит проценты, создайте доход на счёте вклада и выберите категорию «Проценты по вкладам». Ставка в карточке вклада указана для справки.'),
  ('monthly-salary', 60, TRUE, 'How do I add a monthly salary?', 'In Scheduled, create an income rule, select the account and first payment date, then choose Monthly. The server will record the income after it is due. If the actual amount differs, revise the entry in the history. If the payment arrives early and is already in the actual balance, select the future date during reconciliation and enter the reason for skipping it. If a duplicate entry already exists, void it in the history.', 'Как добавить ежемесячную зарплату?', 'В разделе «Запланировано» создайте доход, выберите счёт и дату первого начисления, затем установите повтор «Ежемесячно». Сервер автоматически внесёт запись после наступления даты. При расхождении с фактической суммой исправьте запись в истории. Если деньги поступили раньше и уже входят в фактический остаток, выберите будущую дату при сверке и укажите причину пропуска. Если дублирующая запись уже появилась, отмените её в истории.'),
  ('negative-balance', 70, TRUE, 'Why can my balance be negative?', 'Your recorded outflows exceeded incoming payments and the opening balance. First check your entries and due schedule dates. Then reconcile the ledger balance with the actual balance if they differ.', 'Почему баланс может быть отрицательным?', 'Это означает, что записанные списания превысили поступления и начальный остаток. Сначала проверьте операции и наступившие даты графика. Затем сверьте остаток с фактическим, если они расходятся.'),
  ('contact-support', 80, TRUE, 'How do I contact support?', 'Open the Support tab and choose Email support or Call support.', 'Как связаться с поддержкой?', 'Откройте вкладку «Поддержка» и выберите «Написать на email» или «Позвонить».')
